using UnityEngine;
namespace JerichoPrototype { public sealed class BriefingDialogue : MonoBehaviour { public string speakerName="Jericho Guide"; [TextArea] public string[] pages={"Gameplay paraphrase — Joshua 6.\n\nLead the procession around Jericho through six checkpoints in order.","The one-circuit objective is a gameplay simplification. Follow the numbered route signs."}; public float interactionDistance=3f; public Transform player; public JoshuaController controller; public ThirdPersonCamera cameraController; int page; bool open; void Update(){if(!player)return; if(!open&&Vector3.Distance(transform.position,player.position)<=interactionDistance&&Input.GetKeyDown(KeyCode.E))Open(); else if(open&&Input.GetKeyDown(KeyCode.Escape))Close(); else if(open&&(Input.GetKeyDown(KeyCode.E)||Input.GetKeyDown(KeyCode.Return)||Input.GetKeyDown(KeyCode.Space)))Next();} void Open(){open=true;page=0;if(controller)controller.enabled=false;if(cameraController)cameraController.enabled=false;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;} void Next(){if(page+1<pages.Length)page++;else Close();} void Close(){open=false;if(controller)controller.enabled=true;if(cameraController)cameraController.enabled=true;} void OnGUI(){if(!player)return;if(!open&&Vector3.Distance(transform.position,player.position)<=interactionDistance)GUI.Label(new Rect(30,185,300,25),"Press E to talk");if(open){GUI.Box(new Rect(30,220,600,180),speakerName);GUI.Label(new Rect(50,255,560,90),pages[page]);if(GUI.Button(new Rect(420,360,80,28),page+1<pages.Length?"Next":"Close"))Next();if(GUI.Button(new Rect(510,360,80,28),"Close"))Close();}}}}
